arguments.command:
cd src/Api && cat > Api.slnx <<'E'
<Solution>
  <Project Path="Api/Api.csproj" />
  <Project Path="Api.Tests/Api.Tests.csproj" />
</Solution>
E
cd Api.Tests && sed -i 's|  </ItemGroup>|  </ItemGroup>\n  <ItemGroup>\n    <ProjectReference Include="../Api/Api.csproj" />\n  </ItemGroup>|' Api.Tests.csproj
cat > PayByCardSteps.cs <<'E'
using Reqnroll;

namespace Api.Tests;

[Binding]
public class PayByCardSteps
{
    [Given("a returning customer with a valid card")]
    public void GivenAReturningCustomerWithAValidCard() => throw new NotImplementedException();

    [When("a basket of {int} cents is paid")]
    public void WhenABasketIsPaid(int cents) => throw new NotImplementedException();

    [Then("the payment is accepted for {int} cents")]
    public void ThenThePaymentIsAcceptedFor(int cents) => throw new NotImplementedException();
}
E
cd .. && dotnet build Api.slnx --nologo 2>&1 | tail -15
cd ../Batch && pip install -q pytest ruff 2>&1 | tail -2; ruff check . && pytest -q 2>&1 | tail -3

